import {esc} from '../config.mjs';
export const noticeTargets=[['/#inicio','Início do Reality'],['/#episodios','Vídeo em destaque'],['/#comunidade','Comunidade'],['/#live','Área da LIVE'],['/#enviar','Enviar participação'],['/ir-alem/','Empresas']];
const audienceLabel={inactive:'Ausentes há pelo menos 48 horas',participants:'Aparelhos com último pedido pago',all:'Todos os aparelhos autorizados'};
export function manualNoticePreview(p,count){return `<article class="notice-preview"><span>PRÉVIA · HOCCO</span><h2>${esc(p.title)}</h2><p>${esc(p.body)}</p><strong>Ao tocar: ${esc(noticeTargets.find(x=>x[0]===p.url)?.[1]||'Início do Reality')}</strong><small>${esc(count)} aparelhos autorizados · ${esc(audienceLabel[p.audience])}</small></article>`}
export function noticeHistory(items){return items.map(c=>`<article class="paper notice-history"><div class="row wrap"><h3>${esc(c.title)}</h3><span class="badge">${esc(({queued:'Na fila',completed:'Processamento concluído',cancelled:'Envios interrompidos'})[c.status]||c.status)}</span></div><p>${esc(c.body)}</p><small>${esc(new Date(c.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))} · ${esc(audienceLabel[c.audience]||c.audience)}</small><p>${Number(c.target_count)||0} selecionados · ${Number(c.sent)||0} aceitos pelo serviço push · ${Number(c.pending)||0} pendentes · ${Number(c.failed)||0} falhas · ${Number(c.skipped)||0} ignorados</p>${c.status==='queued'?`<button class="btn secondary" data-notice-cancel="${esc(c.id)}">Interromper próximos envios</button>`:''}</article>`).join('')||'<div class="empty">Nenhum aviso manual criado ainda.</div>'}
export function mountNotices(host,call){let disposed=false,preview=null,requestKey=null,busy=false;host.innerHTML=`<section><div class="control-page-head"><div><h1>Notificações do app</h1><p>Avise sobre vídeos, a LIVE ou novidades reais do Reality.</p></div><button class="btn secondary" data-control-route="management">Voltar à Gestão</button></div><p class="hint" data-notice-channel role="status">Consultando o serviço push…</p><form class="paper" data-notice-form><label for="notice-title">Título</label><input id="notice-title" name="title" required minlength="3" maxlength="80" placeholder="Ex.: Novo vídeo da HOCCO"><label for="notice-body">Mensagem</label><textarea id="notice-body" name="body" required minlength="5" maxlength="240" placeholder="Conte o que a pessoa encontrará ao abrir o app."></textarea><label for="notice-url">Onde abrir ao tocar</label><select id="notice-url" name="url">${noticeTargets.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><label for="notice-audience">Público</label><select id="notice-audience" name="audience">${Object.entries(audienceLabel).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><p class="hint">Somente aparelhos que permitiram notificações do HOCCO. A contagem é de aparelhos, não de pessoas únicas. Não usa WhatsApp nem o telefone de segurança.</p><div class="actions"><button class="btn secondary" type="submit">Conferir prévia e público</button><button class="btn" type="button" data-notice-send disabled>Confirmar envio</button></div><p class="error" data-notice-error role="alert"></p><p data-notice-result role="status"></p><div data-notice-preview></div></form><div class="paper"><h2>Envios e acompanhamento</h2><p>Os avisos confirmados entram na fila automática, verificada a cada cinco minutos. Aceitação pelo serviço push não garante exibição ou leitura. Interromper um aviso impede próximos envios; não recolhe notificações já enviadas.</p><button class="btn secondary" data-notice-refresh>Atualizar envios</button></div><div data-notice-history></div><button class="btn secondary" data-control-route="reactivation">Ver retorno automático e métricas</button></section>`;
 const q=s=>host.querySelector(s),form=q('[data-notice-form]'),send=q('[data-notice-send]'),err=q('[data-notice-error]');
 const payload=()=>Object.fromEntries(new FormData(form).entries());
 function invalidate(){preview=null;requestKey=null;send.disabled=true;q('[data-notice-preview]').innerHTML='';q('[data-notice-result]').textContent='Confira a prévia novamente após editar.'}
 form.addEventListener('input',invalidate);form.addEventListener('change',invalidate);
 async function history(){try{const d=await call('admin.notices.history',{});if(disposed)return;q('[data-notice-channel]').textContent=d.channelReady?'Notificações push configuradas. Nenhum aviso é enviado antes da sua confirmação.':'Serviço push indisponível. Os avisos não serão enviados enquanto estiver desativado.';q('[data-notice-history]').innerHTML=noticeHistory(d.campaigns||[]);host.querySelectorAll('[data-notice-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm('Interromper os próximos envios deste aviso? Os já enviados não podem ser recolhidos.'))return;b.disabled=true;try{await call('admin.notices.cancel',{id:b.dataset.noticeCancel,confirmed:true});if(!disposed)await history()}catch(e){if(!disposed){err.textContent=e.message;b.disabled=false}}})}catch(e){if(!disposed)err.textContent=e.message}}
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;send.disabled=true;err.textContent='';const p=payload(),snapshot=JSON.stringify(p);try{const d=await call('admin.notices.preview',{payload:p});if(disposed||JSON.stringify(payload())!==snapshot)return;preview={payload:p,snapshot,count:Number(d.recipients)||0};requestKey=crypto.randomUUID();q('[data-notice-preview]').innerHTML=manualNoticePreview(p,preview.count);q('[data-notice-result]').textContent=preview.count?'Confira o conteúdo e o público antes de confirmar.':'Nenhum aparelho autorizado neste público. Não será criado um envio.';send.disabled=!preview.count}catch(e){if(!disposed)err.textContent=e.message}finally{busy=false}};
 send.onclick=async()=>{if(busy||!preview||preview.snapshot!==JSON.stringify(payload()))return;if(!confirm('Confirmar este aviso para '+preview.count+' aparelhos autorizados?'))return;busy=true;send.disabled=true;err.textContent='';try{const d=await call('admin.notices.enqueue',{payload:preview.payload,requestKey,expectedCount:preview.count,confirmed:true});if(disposed)return;q('[data-notice-result]').textContent='Aviso confirmado para '+d.targetCount+' aparelhos. A fila automática fará os envios.';preview=null;delete form.dataset.unsaved;await history()}catch(e){if(!disposed){err.textContent=e.message;if(/público mudou/i.test(e.message)){preview=null;requestKey=null;send.disabled=true}else send.disabled=false}}finally{busy=false}};
 q('[data-notice-refresh]').onclick=history;history();return()=>{disposed=true;host.replaceChildren()};
}
